def evaluate(expr: str) -> float:
    """
    Evaluate an arithmetic expression containing non‑negative numbers (integers or decimals),
    operators + - * /, parentheses, spaces, and unary minus/plus.
    Normal precedence: parentheses > unary +/- > * / > + -.
    """
    class Parser:
        __slots__ = ('s', 'i', 'n')

        def __init__(self, s: str):
            self.s = s
            self.i = 0
            self.n = len(s)

        def _skip_spaces(self):
            while self.i < self.n and self.s[self.i].isspace():
                self.i += 1

        def _peek(self):
            self._skip_spaces()
            if self.i < self.n:
                return self.s[self.i]
            return None

        def _consume(self, expected=None):
            self._skip_spaces()
            if self.i < self.n:
                ch = self.s[self.i]
                if expected is None or ch == expected:
                    self.i += 1
                    return ch
            return None

        def _parse_number(self) -> float:
            self._skip_spaces()
            start = self.i
            # Accept digits and at most one dot; float() will validate the format.
            while self.i < self.n and (self.s[self.i].isdigit() or self.s[self.i] == '.'):
                self.i += 1
            num_str = self.s[start:self.i]
            if not num_str:
                raise ValueError("Expected number")
            try:
                return float(num_str)
            except ValueError:
                raise ValueError(f"Invalid number format: {num_str}")

        def _parse_primary(self) -> float:
            ch = self._peek()
            if ch == '(':
                self._consume('(')
                val = self._parse_expr()
                if self._peek() != ')':
                    raise ValueError("Expected ')'")
                self._consume(')')
                return val
            elif ch is not None and (ch.isdigit() or ch == '.'):
                return self._parse_number()
            else:
                raise ValueError(f"Unexpected character: {ch!r}")

        def _parse_factor(self) -> float:
            ch = self._peek()
            if ch == '+':
                self._consume('+')
                return self._parse_factor()
            elif ch == '-':
                self._consume('-')
                return -self._parse_factor()
            else:
                return self._parse_primary()

        def _parse_term(self) -> float:
            val = self._parse_factor()
            while True:
                ch = self._peek()
                if ch == '*':
                    self._consume('*')
                    val *= self._parse_factor()
                elif ch == '/':
                    self._consume('/')
                    denom = self._parse_factor()
                    if denom == 0:
                        raise ZeroDivisionError("Division by zero")
                    val /= denom
                else:
                    break
            return val

        def _parse_expr(self) -> float:
            val = self._parse_term()
            while True:
                ch = self._peek()
                if ch == '+':
                    self._consume('+')
                    val += self._parse_term()
                elif ch == '-':
                    self._consume('-')
                    val -= self._parse_term()
                else:
                    break
            return val

    parser = Parser(expr)
    result = parser._parse_expr()
    parser._skip_spaces()
    if parser.i != parser.n:
        raise ValueError("Unexpected trailing characters")
    return result
