def is_valid_ipv4(s: str) -> bool:
    # No surrounding whitespace allowed
    if s != s.strip():
        return False

    parts = s.split('.')
    if len(parts) != 4:
        return False

    for part in parts:
        # Each part must be non-empty and contain only digits
        if not part or not part.isdigit():
            return False
        # No leading zeros unless the part is exactly "0"
        if len(part) > 1 and part[0] == '0':
            return False
        # Numeric value must be in range 0-255
        num = int(part)
        if num < 0 or num > 255:
            return False

    return True
